#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeRChatClient: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = RChatClient

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> RChatClient {
        return RChatClient(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: RChatClient) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RChatClient {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: RChatClient, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}




#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeRChatClient_lift(_ pointer: UnsafeMutableRawPointer) throws -> RChatClient {
    return try FfiConverterTypeRChatClient.lift(pointer)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeRChatClient_lower(_ value: RChatClient) -> UnsafeMutableRawPointer {
    return FfiConverterTypeRChatClient.lower(value)
}


/**
 * Configuration for the RChat client. `Debug` never prints the identity
 * seed (C-10); the client takes the seed out of its copy at creation.
 */
public struct ClientConfig {
    public var serverUrl: String
    /**
     * Never deserialized with the rest (R1-3): a later field failing would
     * free a plain copy of it. `rchat_connect` reads it apart, wiped.
     */
    public var identityKeySeed: String?
    public var connectionTimeoutSecs: UInt32
    public var reconnectMaxAttempts: UInt32
    public var messageRetryCount: UInt32
    public var enableDeliveryConfirmation: Bool
    public var keepaliveIntervalSecs: UInt32
    /**
     * BoringSSL ClientHello profile (default `Chrome`: the TLS 1.3-only
     * profile). No profile reproduces a real browser's fingerprint.
     */
    public var tlsFingerprint: TlsFingerprint
    /**
     * `ws://` (dev) only: the relay's configured `dev_origin`, if it differs
     * from the server URL's `scheme://host:port`.
     */
    public var devOrigin: String?
    /**
     * Saved relay identity pin for this server (`rk:1:…`), if any (spec §4.9).
     */
    public var relayPin: String?
    /**
     * Version of the saved relay identity.
     */
    public var relayPinVersion: UInt32?
    /**
     * Refuse to trust a relay on first use (require `relay_pin`).
     */
    public var relayPinStrict: Bool
    /**
     * This identity's key version (0 for a new account; +1 per rotation).
     */
    public var identityVersion: UInt32
    /**
     * The last ≤ 3 rotation links leading to this identity (196-byte links, hex, concatenated).
     */
    public var rotationLinksHex: String?
    /**
     * When this identity was rotated in (Unix seconds).
     */
    public var rotatedAtUnix: UInt64?
    /**
     * Identities pinned at rotation time that have not yet been reached
     * under the new identity (round-2 M3; persisted by the app, which
     * removes a peer on `on_circuit_established`).
     */
    public var rotationUnreachedHex: [String]?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(serverUrl: String, 
        /**
         * Never deserialized with the rest (R1-3): a later field failing would
         * free a plain copy of it. `rchat_connect` reads it apart, wiped.
         */identityKeySeed: String?, connectionTimeoutSecs: UInt32, reconnectMaxAttempts: UInt32, messageRetryCount: UInt32, enableDeliveryConfirmation: Bool, keepaliveIntervalSecs: UInt32, 
        /**
         * BoringSSL ClientHello profile (default `Chrome`: the TLS 1.3-only
         * profile). No profile reproduces a real browser's fingerprint.
         */tlsFingerprint: TlsFingerprint, 
        /**
         * `ws://` (dev) only: the relay's configured `dev_origin`, if it differs
         * from the server URL's `scheme://host:port`.
         */devOrigin: String?, 
        /**
         * Saved relay identity pin for this server (`rk:1:…`), if any (spec §4.9).
         */relayPin: String?, 
        /**
         * Version of the saved relay identity.
         */relayPinVersion: UInt32?, 
        /**
         * Refuse to trust a relay on first use (require `relay_pin`).
         */relayPinStrict: Bool, 
        /**
         * This identity's key version (0 for a new account; +1 per rotation).
         */identityVersion: UInt32, 
        /**
         * The last ≤ 3 rotation links leading to this identity (196-byte links, hex, concatenated).
         */rotationLinksHex: String?, 
        /**
         * When this identity was rotated in (Unix seconds).
         */rotatedAtUnix: UInt64?, 
        /**
         * Identities pinned at rotation time that have not yet been reached
         * under the new identity (round-2 M3; persisted by the app, which
         * removes a peer on `on_circuit_established`).
         */rotationUnreachedHex: [String]?) {
        self.serverUrl = serverUrl
        self.identityKeySeed = identityKeySeed
        self.connectionTimeoutSecs = connectionTimeoutSecs
        self.reconnectMaxAttempts = reconnectMaxAttempts
        self.messageRetryCount = messageRetryCount
        self.enableDeliveryConfirmation = enableDeliveryConfirmation
        self.keepaliveIntervalSecs = keepaliveIntervalSecs
        self.tlsFingerprint = tlsFingerprint
        self.devOrigin = devOrigin
        self.relayPin = relayPin
        self.relayPinVersion = relayPinVersion
        self.relayPinStrict = relayPinStrict
        self.identityVersion = identityVersion
        self.rotationLinksHex = rotationLinksHex
        self.rotatedAtUnix = rotatedAtUnix
        self.rotationUnreachedHex = rotationUnreachedHex
    }
}



extension ClientConfig: Equatable, Hashable {
    public static func ==(lhs: ClientConfig, rhs: ClientConfig) -> Bool {
        if lhs.serverUrl != rhs.serverUrl {
            return false
        }
        if lhs.identityKeySeed != rhs.identityKeySeed {
            return false
        }
        if lhs.connectionTimeoutSecs != rhs.connectionTimeoutSecs {
            return false
        }
        if lhs.reconnectMaxAttempts != rhs.reconnectMaxAttempts {
            return false
        }
        if lhs.messageRetryCount != rhs.messageRetryCount {
            return false
        }
        if lhs.enableDeliveryConfirmation != rhs.enableDeliveryConfirmation {
            return false
        }
        if lhs.keepaliveIntervalSecs != rhs.keepaliveIntervalSecs {
            return false
        }
        if lhs.tlsFingerprint != rhs.tlsFingerprint {
            return false
        }
        if lhs.devOrigin != rhs.devOrigin {
            return false
        }
        if lhs.relayPin != rhs.relayPin {
            return false
        }
        if lhs.relayPinVersion != rhs.relayPinVersion {
            return false
        }
        if lhs.relayPinStrict != rhs.relayPinStrict {
            return false
        }
        if lhs.identityVersion != rhs.identityVersion {
            return false
        }
        if lhs.rotationLinksHex != rhs.rotationLinksHex {
            return false
        }
        if lhs.rotatedAtUnix != rhs.rotatedAtUnix {
            return false
        }
        if lhs.rotationUnreachedHex != rhs.rotationUnreachedHex {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(serverUrl)
        hasher.combine(identityKeySeed)
        hasher.combine(connectionTimeoutSecs)
        hasher.combine(reconnectMaxAttempts)
        hasher.combine(messageRetryCount)
        hasher.combine(enableDeliveryConfirmation)
        hasher.combine(keepaliveIntervalSecs)
        hasher.combine(tlsFingerprint)
        hasher.combine(devOrigin)
        hasher.combine(relayPin)
        hasher.combine(relayPinVersion)
        hasher.combine(relayPinStrict)
        hasher.combine(identityVersion)
        hasher.combine(rotationLinksHex)
        hasher.combine(rotatedAtUnix)
        hasher.combine(rotationUnreachedHex)
    }
}


