/**
 * A knock from someone not yet accepted (spec §6.3). Intro fields are
 * empty / 0 when the knock carried no intro.
 */
public struct MessageRequest {
    public var identityHex: String
    public var agreementHex: String
    public var issuedHour: UInt64
    public var introMessageIdHex: String
    public var introText: String
    public var introSentAtMs: UInt64
    /**
     * The sender's key version from its knock's rotation block (0 if none).
     */
    public var keyVersion: UInt32

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(identityHex: String, agreementHex: String, issuedHour: UInt64, introMessageIdHex: String, introText: String, introSentAtMs: UInt64, 
        /**
         * The sender's key version from its knock's rotation block (0 if none).
         */keyVersion: UInt32) {
        self.identityHex = identityHex
        self.agreementHex = agreementHex
        self.issuedHour = issuedHour
        self.introMessageIdHex = introMessageIdHex
        self.introText = introText
        self.introSentAtMs = introSentAtMs
        self.keyVersion = keyVersion
    }
}



extension MessageRequest: Equatable, Hashable {
    public static func ==(lhs: MessageRequest, rhs: MessageRequest) -> Bool {
        if lhs.identityHex != rhs.identityHex {
            return false
        }
        if lhs.agreementHex != rhs.agreementHex {
            return false
        }
        if lhs.issuedHour != rhs.issuedHour {
            return false
        }
        if lhs.introMessageIdHex != rhs.introMessageIdHex {
            return false
        }
        if lhs.introText != rhs.introText {
            return false
        }
        if lhs.introSentAtMs != rhs.introSentAtMs {
            return false
        }
        if lhs.keyVersion != rhs.keyVersion {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(identityHex)
        hasher.combine(agreementHex)
        hasher.combine(issuedHour)
        hasher.combine(introMessageIdHex)
        hasher.combine(introText)
        hasher.combine(introSentAtMs)
        hasher.combine(keyVersion)
    }
}


