/**
 * Connection status for UI updates
 */

public enum ConnectionStatus {
    
    case disconnected
    case connecting
    case connected
    case reconnecting(attempt: UInt32, maxAttempts: UInt32
    )
    case error(message: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeConnectionStatus: FfiConverterRustBuffer {
    typealias SwiftType = ConnectionStatus

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ConnectionStatus {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .disconnected
        
        case 2: return .connecting
        
        case 3: return .connected
        
        case 4: return .reconnecting(attempt: try FfiConverterUInt32.read(from: &buf), maxAttempts: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 5: return .error(message: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ConnectionStatus, into buf: inout [UInt8]) {
        switch value {
        
        
        case .disconnected:
            writeInt(&buf, Int32(1))
        
        
        case .connecting:
            writeInt(&buf, Int32(2))
        
        
        case .connected:
            writeInt(&buf, Int32(3))
        
        
        case let .reconnecting(attempt,maxAttempts):
            writeInt(&buf, Int32(4))
            FfiConverterUInt32.write(attempt, into: &buf)
            FfiConverterUInt32.write(maxAttempts, into: &buf)
            
        
        case let .error(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


