     * Default: the TLS 1.3-only, ALPN http/1.1 BoringSSL ClientHello
     */
    case chrome
    /**
     * Same ClientHello as `Chrome` (name kept for config compatibility)
     */
    case firefox
    /**
     * Same ClientHello as `Chrome` (name kept for config compatibility)
     */
    case safari
    /**
     * BoringSSL's default ClientHello (`connect_standard`)
     */
    case none
}


